  on mute =>> idle do emit notify
", "ack ack ack low tick low", "start: -> idle
ack: ignored
ack: ignored
ack: ignored
low: ignored
tick: ignored
low: ignored
final idle"},
        {"initial idle
phase idle
  on low =>> muted do emit lock
  on mute =>> falling do emit close, emit notify
  on high =>> falling do emit hum, emit open
phase falling
  on low =>> idle do emit reset, emit open
phase rising
  on tick =>> idle do emit beep
  on low =>> falling
  on mute =>> idle do emit bad, emit notify
phase muted
  on low =>> rising
", "tick high ack storm mute low ack", "start: -> idle
tick: ignored
high: idle -> falling | hum open
ack: ignored
storm: ignored
mute: ignored
low: falling -> idle | reset open
ack: ignored
final idle"},
        };
        int failed = 0;
        for (int i = 0; i < cases.length; i++) {
            String[] c = cases[i];
            String want = c[2];
            String got;
            try {
                got = Statemachine.machine(c[0], c[1]);
            } catch (Throwable e) {
                got = "EXCEPTION " + e;
            }
            if (!want.equals(got)) {
                failed++;
                System.out.println("case " + i + " FAILED
  args: " + String.join(" | ", java.util.Arrays.copyOf(c, 2)) + "
  got:  " + got + "
  want: " + want);
            }
        }
        System.out.println((cases.length - failed) + "/" + cases.length + " cases passed");
        if (failed > 0) System.exit(1);
    }
}

